    'fc.help_body' => 'Spravuje zkratkové kódy vytáčené z telefonu (např. <code>*78</code>): Nerušit (DND), přesměrování hovorů, skupinové/přímé zvednutí hovoru, odposlech hovoru, přihlášení/odhlášení z fronty (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), pozastavení / obnovení ve frontě (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
