    'asterisk_settings.rtp_help_body' => 'Určuje, který rozsah portů přenáší zvuk (RTP) a zda Asterisk odmítá zvuk přicházející z neočekávaného zdroje. Tento soubor (<code>/etc/asterisk/rtp.conf</code>) nyní generuje panel; ruční úpravy na serveru budou při dalším „Použít“ ztraceny.',
