    'asterisk_settings.field_rtp_end' => 'Koncový port RTP',
    'asterisk_settings.rtp_end_help' => 'Konec rozsahu. coturn (TURN relay) používá 13479-14999 — překryv naruší zvuk WebRTC a při uložení je odmítnut.',
    'asterisk_settings.field_rtp_strict' => 'Striktní RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Je-li povoleno, Asterisk tiše zahazuje zvuk přicházející z jakéhokoli jiného zdroje než naučené vzdálené adresy/portu (ochrana proti útokům). Pokud protější ústředna posílá média z neočekávaného portu, způsobí to tichou poruchu „bez zvuku“ bez stopy v protokolu — pro diagnostiku lze dočasně vypnout.',
