    'trunks.connection_mode_register' => 'Příchozí registrace (protistrana se registruje u nás)',
    'trunks.connection_mode_help' => 'Podle IP: protistrana je identifikována svou IP adresou a její kontakt je statický — doporučený režim pro protistranu s pevnou IP ve stejné síti. Příchozí registrace: protistrana nám posílá SIP REGISTER a její adresa se zjistí z této registrace. Tento režim vyžaduje uživatelské jméno a heslo; protistrana jimi ověřuje svou registraci i hovory.',
