    'sound_packs.title' => 'Oficiální zvukové balíčky Asterisku',
    'sound_packs.help_title' => 'Zvukové balíčky Asterisku',
    'sound_packs.help_body' => 'Stahuje a instaluje oficiální systémové výzvy a hudbu při čekání Asterisku z <code>downloads.asterisk.org</code>. Každý balíček představuje jeden jazyk v jednom formátu; Asterisk přehrává formát odpovídající kodeku hovoru, jinak překóduje (g722 pro G.722, ulaw/alaw pro operátory).<br>- <strong>Core:</strong> systémové výzvy, číslice, hlasová schránka. <strong>Extra:</strong> další výzvy; nejprve musí být nainstalován balíček Core stejného jazyka.<br>- <strong>Hudba při čekání (opsound):</strong> instaluje se do <code>/var/lib/asterisk/moh/opsound</code>; pro přehrávání vytvořte na kartě Hudba při čekání třídu MOH s názvem <strong>opsound</strong>.<br>- <strong>Türkçe (AiPBX):</strong> vlastní turecké výzvy AiPBX (vydání na GitHubu, ověřeno SHA256); výchozím jazykem je turečtina, takže jejich odebráním systémové výzvy ztichnou. Odebrání smaže pouze soubory, které balíček nainstaloval.',
