    'system_update.page_title' => 'Aktualizace systému',
    'system_update.help_title' => 'Jak aktualizace probíhá?',
    'system_update.help_body' => 'Aktualizace nejprve zálohuje databázi, nastavení a konfiguraci Asterisku, poté nainstaluje novou verzi a otestuje, že vše funguje. Pokud cokoli selže, automaticky se vrátí k předchozí verzi. Během aktualizace se Asterisk restartuje: probíhající hovory se přeruší, proto se aktualizace nespustí, pokud probíhají hovory. Lze ji spustit také na serveru: <code>sudo aipbx-update</code>',
