    'certificates.help_title' => 'Průvodce certifikáty',
    'certificates.help_body' => 'Portál (HTTPS), WebRTC TURNS a SIP-TLS/WSS sdílejí jeden certifikát; změny provedené zde se uplatní současně v Apache, coturn a Asterisku. <b>Let\'s Encrypt</b> je zdarma a obnovuje se sám; doména musí směřovat na tento server a port 80 musí být dostupný z internetu. Má-li vaše organizace vlastní certifikát, <b>nahrajte jej</b> (PEM nebo PFX); nahrané certifikáty se automaticky neobnovují, nahrajte nový před vypršením platnosti. U certifikátu <b>podepsaného sebou samým</b> prohlížeče zobrazují varování a TURNS v prohlížečích nefunguje: hovory WebRTC za firewallem mohou být bez zvuku.',
