    'queue_reports.help_title' => 'Průvodce reporty front',
    'queue_reports.help_body' => 'Každý hovor, který vstoupí do fronty, se počítá jednou. <b>Přijaté</b>: spojené s agentem. <b>Ztracené</b>: volající zavěsil během čekání nebo vypršel časový limit fronty. <b>Krátké opuštění</b>: zavěšeno do %d sekund; nezapočítává se do úrovně služeb. <b>Úroveň služeb</b>: hovory přijaté v cílovém čase vůči všem hovorům kromě krátkých opuštění. <b>ASA</b>: průměrné čekání přijatých hovorů. <b>AHT</b>: průměrná doba hovoru. <b>Míra přijetí</b> (agent): jak často agent přijal hovor, když mu fronta vyzváněla. <b>Zpětné volání</b>: ztracený hovor se považuje za vyřešený, pokud bylo jeho číslo později voláno z linky, nebo volalo znovu a bylo přijato. Data pocházejí z protokolu front Asterisku; report lze stáhnout jako PDF nebo Excel.',
