    'ai_models.help_body' => 'Spouští AI modely přímo na ústředně PBX: text a zvuk nikdy neopouštějí server, bez klíčů API a dalších nákladů. Nejprve nainstalujte <strong>místní běhové prostředí AI</strong> (přibližně 160 MB na disku, staženo pouze jednou), poté stáhněte potřebné modely a přijměte jejich licenci. Načtený model využívá paměť a procesor; test rychlosti ukáže, zda je na tomto serveru dostatečně rychlý. Hovory mají vždy přednost: služba běží s nižší prioritou procesoru a s limitem paměti. Viz docs/local-ai.md.',
