    'ai_apps.help_title' => 'AI aplikace s vlastními čísly',
    'ai_apps.help_body' => 'AI aplikace přijme hovor, provede svůj úkol a přepojí hovor na cíl. Přidělte jí interní číslo pro přímé volání, nebo ji vyberte jako cíl v IVR, příchozích trasách a časových podmínkách („AI aplikace“). <strong>Hlášení s hodnotami</strong>: text čtený volajícímu hlasovým modelem tohoto serveru s vloženými hodnotami — {caller_number}, {caller_name}, {did} pocházejí z hovoru, jakékoli další {name} z vašeho systému prostřednictvím adresy vyhledávání. Změny se projeví kliknutím na <strong>Použít</strong>.',
