    'ai_cloud.help_body' => 'Účty poskytovatelů cloudové AI na jednom místě: hlas, převod řeči na text, jazykové modely (Gemini, Gemma, GPT, Llama …) a vnoření (embeddings). Zadejte klíč, otestujte jej a pro každou úlohu a jazyk zvolte použitý stroj: místní model tohoto serveru nebo cloudového poskytovatele. Bezplatné tarify jsou označeny; využití v tomto měsíci je zobrazeno u každého poskytovatele.',
