    'ai_tts.help_title' => 'Průvodce Cloud TTS',
    'ai_tts.help_body' => 'Převádí text na přirozenou řeč pomocí cloudových služeb (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Výsledek si poslechněte, stáhněte jako MP3 nebo jedním kliknutím uložte jako <b>hlášení</b>: převede se do formátu Asterisku (WAV 8 kHz) a přidá do Zvuků &amp; hlášení pro IVR, příchozí trasy a časové podmínky (projeví se po použití změn). <b>Tyto služby jsou placené</b> a účtují se podle počtu znaků; každá syntéza se ukládá do historie včetně počtu znaků. Přístupové klíče získáte v konzoli jednotlivých poskytovatelů, ukládají se šifrovaně a na stránce se již nikdy nezobrazí.',
