    'push.help_layer0' => '<strong>Vrstva 0 (bez závislostí - výchozí):</strong> trvalé spojení WSS, služba v popředí <code>specialUse</code> kompatibilní s Androidem 15 a hlídač <code>AlarmManager</code> odolný vůči režimu Doze, který ji oživuje. Není potřeba žádná externí služba; hovory přicházejí, i když je zařízení nečinné nebo má vypnutou obrazovku.',
