    'mailtpl.voicemail.body' => '<p>Dobrý den, {name},</p><p>ve schránce <strong>{mailbox}</strong> máte novou hlasovou zprávu.</p><ul><li><strong>Od:</strong> {caller}</li><li><strong>Přijato:</strong> {date}</li><li><strong>Délka:</strong> {duration}</li></ul><p>Pokud je nahrávka přiložena, můžete si ji přehrát přímo zde. Poslechnout si ji můžete také na portálu ({portal_link}) nebo vytočením *97.</p>',
