    'mailtpl.fax_sent.subject' => 'Fax doručen na {destination} (#{fax_id})',
    'mailtpl.fax_sent.body' => '<p>Váš fax byl doručen.</p><ul><li><strong>Komu:</strong> {destination}</li><li><strong>Stránky:</strong> {pages}</li><li><strong>Čas:</strong> {date}</li></ul><p>Odeslané faxy: {portal_link}</p>',
