    'storage.help_title' => 'Kde se ukládají soubory chatu',
    'storage.help_body' => '<p>Přílohy chatu, jejich náhledy a obrázky skupin se ve výchozím stavu ukládají na disk serveru (<code>/var/lib/aipbx/chat_files</code>). S úložištěm kompatibilním s S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) se místo toho ukládají do bucketu a velké soubory nezatěžují ústřednu.</p><p>Stahování dál probíhá přes službu chatu, takže soubory chatu mohou otevřít jen jeho účastníci; bucket může zůstat soukromý. Soubory uložené před přepnutím se dál poskytují z disku, dokud je nepřesunete. Nastavení bucketu se před uložením ověří.</p><p>Nahrávky hovorů, hlasová schránka a faxy zůstávají na místním disku.</p>',
