    'netsvc.help_title' => 'Síťové služby',
    'netsvc.help_body' => 'Stolní telefony samy najdou provisioningový server, když DHCP server rozdává jeho adresu (option 66). DHCP a TFTP se zapínají zvlášť. Při vypnutém <strong>DHCP serveru</strong> zůstává váš vlastní DHCP server: nastavte na něm volby uvedené níže. Při zapnutém AiPBX rozdává adresy na jednom rozhraní nebo VLAN. <strong>TFTP server</strong> poskytuje nahrané boot soubory a firmware. Konfigurace jednotlivých telefonů (se SIP heslem) se vždy poskytuje přes HTTPS, nikdy přes TFTP.',
